// Package discoverycache implements the per-source on-disk cache described in
// ADR-012. It provides a two-tier lock + long-lived refresh marker pattern so
// that slow discovery IO (PTY ~30 s, HTTP ~316 ms) never blocks UI reads.
//
// Public surface: Cache.Read, Cache.Refresh, Cache.MaybeRefresh, Cache.Prune.
// The Refresher function is injected; the cache manages single-flight
// deduplication, atomic writes, and crash recovery.
package discoverycache

import (
	"context"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"

	"golang.org/x/sync/singleflight"
)

const (
	lockAcquisitionTimeout = 100 * time.Millisecond
	lockPollInterval       = 5 * time.Millisecond
	waitPollInterval       = 250 * time.Millisecond
	stalenessMultiplier    = time.Duration(2)
)

// Cache is the root handle. Root is the base directory (e.g. ~/.cache/fizeau).
// Each Cache instance owns one in-process singleflight.Group; a new Cache per
// process is the normal usage.
type Cache struct {
	Root string
	sf   singleflight.Group
}

// Source describes one cacheable data stream (one file under Root/Tier/Name.json).
type Source struct {
	// Tier is "discovery" or "runtime".
	Tier string
	// Name is the kebab-case source identifier (e.g. "openrouter").
	Name string
	// TTL controls freshness: Read returns Fresh=true when Age < TTL.
	TTL time.Duration
	// RefreshDeadline is the maximum time a refresh is expected to take.
	// Also controls the staleness threshold: 2 × RefreshDeadline.
	RefreshDeadline time.Duration
}

func (s Source) key() string { return s.Tier + "/" + s.Name }

// ReadResult is the output of Cache.Read.
type ReadResult struct {
	// Data is the raw bytes from the cache file; nil if no file exists.
	Data []byte
	// Age is how long ago the data was written (0 if absent).
	Age time.Duration
	// Fresh is true when Age < TTL and Data is non-nil.
	Fresh bool
	// Stale is true when Data is nil or Age >= TTL.
	Stale bool
}

// Refresher is the source-fetch function injected by the caller. The cache
// handles single-flight deduplication, the atomic write, and marker lifecycle.
type Refresher func(ctx context.Context) ([]byte, error)

// Read returns cached data without any IO beyond reading the local file.
// It never blocks on network or PTY. If no cache file exists, Data is nil and
// Stale is true. Stale data is always returned without error; the caller
// decides whether to trigger a background refresh.
func (c *Cache) Read(s Source) (ReadResult, error) {
	path := c.dataPath(s)
	data, err := os.ReadFile(path) // #nosec G304
	if errors.Is(err, os.ErrNotExist) {
		return ReadResult{Stale: true}, nil
	}
	if err != nil {
		return ReadResult{}, err
	}
	info, err := os.Stat(path)
	if err != nil {
		// File was just there; best-effort fallback.
		return ReadResult{Data: data, Stale: true}, nil
	}
	age := time.Since(info.ModTime())
	if age < 0 {
		age = 0
	}
	fresh := age < s.TTL
	return ReadResult{
		Data:  data,
		Age:   age,
		Fresh: fresh,
		Stale: !fresh,
	}, nil
}

// Prune removes data files (and their sidecar lock/marker/tmp files) for
// sources not listed in activeSources. Sources with an active .refreshing
// marker are skipped. Prune acquires the tier-1 lock before removing each
// source's files.
func (c *Cache) Prune(activeSources []Source) error {
	active := make(map[string]bool, len(activeSources))
	for _, s := range activeSources {
		active[s.key()] = true
	}

	return filepath.WalkDir(c.Root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return nil
		}
		if !strings.HasSuffix(d.Name(), ".json") {
			return nil
		}
		rel, rerr := filepath.Rel(c.Root, path)
		if rerr != nil {
			return nil
		}
		parts := strings.SplitN(rel, string(filepath.Separator), 2)
		if len(parts) != 2 {
			return nil
		}
		tier := parts[0]
		name := strings.TrimSuffix(parts[1], ".json")
		if strings.ContainsRune(name, filepath.Separator) {
			return nil // nested dir, skip
		}

		if active[tier+"/"+name] {
			return nil
		}

		s := Source{Tier: tier, Name: name}

		// Skip sources with an active refresh in progress.
		m, _ := readMarker(c.markerPath(s))
		if isMarkerActiveForPrune(m) {
			return nil
		}

		release, lerr := c.acquireLock(s)
		if lerr != nil {
			return nil // can't lock; skip this source
		}
		defer release()

		// Re-check under lock.
		m2, _ := readMarker(c.markerPath(s))
		if isMarkerActiveForPrune(m2) {
			return nil
		}

		_ = os.Remove(c.dataPath(s))
		_ = os.Remove(c.markerPath(s))
		_ = os.Remove(c.tmpPath(s))
		return nil
	})
}

// ---- internal ---------------------------------------------------------------

type claimResult struct {
	claimed bool
	marker  *refreshMarker
}

// claimRefresh implements Algorithm 1 from ADR-012. Must be called with the
// source directory already created (ensured by refreshAndCommit).
func (c *Cache) claimRefresh(s Source) (claimResult, error) {
	release, err := c.acquireLock(s)
	if err != nil {
		return claimResult{}, err
	}
	defer release()

	existing, _ := readMarker(c.markerPath(s))
	if existing != nil {
		if isStale(s, existing) {
			_ = os.Remove(c.markerPath(s))
		} else {
			return claimResult{claimed: false, marker: existing}, nil
		}
	}

	m := &refreshMarker{
		PID:       os.Getpid(),
		StartedAt: time.Now().UTC(),
		Deadline:  time.Now().UTC().Add(s.RefreshDeadline),
	}
	if werr := writeMarker(c.markerPath(s), m); werr != nil {
		return claimResult{}, werr
	}
	return claimResult{claimed: true}, nil
}

// refreshAndCommit implements Algorithm 2 from ADR-012.
func (c *Cache) refreshAndCommit(s Source, fn Refresher) error {
	if err := os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750); err != nil {
		return err
	}

	claim, err := c.claimRefresh(s)
	if err != nil {
		return err
	}
	if !claim.claimed {
		// Another process is refreshing; wait for it.
		return c.waitForRefresh(s, claim.marker)
	}

	// We hold the claim. Run slow IO outside any lock.
	data, fetchErr := fn(context.Background())
	if fetchErr != nil {
		c.releaseMarker(s)
		return fetchErr
	}

	if werr := atomicWrite(c.dataPath(s), data); werr != nil {
		c.releaseMarker(s)
		return werr
	}

	c.releaseMarker(s)
	return nil
}

// waitForRefresh implements Algorithm 3 from ADR-012. Polls until the marker
// disappears or becomes stale, then returns (data has been written).
func (c *Cache) waitForRefresh(s Source, m *refreshMarker) error {
	// Poll until deadline + staleness_threshold or s.RefreshDeadline, whichever first.
	threshold := s.RefreshDeadline * stalenessMultiplier
	absoluteDeadline := m.Deadline.Add(threshold)
	maxWait := time.Now().Add(s.RefreshDeadline)
	if maxWait.Before(absoluteDeadline) {
		absoluteDeadline = maxWait
	}

	for time.Now().Before(absoluteDeadline) {
		time.Sleep(waitPollInterval)

package discoverycache

// Algorithm 6 from ADR-012: in-process singleflight composition.
//
// Within a process, singleflight.Group ensures at most one goroutine runs
// refreshAndCommit per source key. Across processes, the file-based marker
// (Algorithm 1) provides the same guarantee. The two layers compose: if
// goroutine A holds the singleflight key, goroutine B blocks on the same
// goroutine and gets the same result — no redundant file IO. If process B
// wins the singleflight but process A already holds the file marker, process B
// falls into waitForRefresh.

// Refresh forces a synchronous refresh regardless of TTL. If a refresh is
// already in flight (another goroutine or process), Refresh waits for it to
// complete. In-process callers share one goroutine via singleflight.
func (c *Cache) Refresh(s Source, fn Refresher) error {
	_, err, _ := c.sf.Do(s.key(), func() (interface{}, error) {
		return nil, c.refreshAndCommit(s, fn)
	})
	return err
}

// MaybeRefresh triggers a background refresh when the data is stale or absent,
// then returns immediately. The caller always gets data from Read; MaybeRefresh
// only schedules the replenishment. Multiple concurrent callers for the same
// source share one background goroutine via singleflight.
func (c *Cache) MaybeRefresh(s Source, fn Refresher) {
	res, err := c.Read(s)
	if err != nil || res.Fresh {
		return
	}
	go func() {
		_, _, _ = c.sf.Do(s.key(), func() (interface{}, error) {
			return nil, c.refreshAndCommit(s, fn)
		})
	}()
}

		time.Sleep(waitPollInterval)
		current, _ := readMarker(c.markerPath(s))
		if current == nil || isStale(s, current) {
			return nil
		}
	}
	return nil // timed out; caller will read whatever is on disk
}

// releaseMarker removes the .refreshing marker under the tier-1 lock, but
// only if our PID is still recorded (guard against PID-reuse races, per §2
// of refreshAndCommit pseudocode in ADR-012).
func (c *Cache) releaseMarker(s Source) {
	release, err := c.acquireLock(s)
	if err != nil {
		return
	}
	defer release()
	m, _ := readMarker(c.markerPath(s))
	if m != nil && m.PID == os.Getpid() {
		_ = os.Remove(c.markerPath(s))
	}
}

// ---- path helpers -----------------------------------------------------------

func (c *Cache) dataPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".json")
}

func (c *Cache) lockPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".lock")
}

func (c *Cache) markerPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".refreshing")
}

func (c *Cache) tmpPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".json.tmp")
}

package discoverycache

// Multi-process test suite for ADR-012 §9.
//
// Tests that require a separate OS process (SIGKILL, cross-process locking)
// use the standard TestHelperProcess pattern: the test binary spawns itself
// with -test.run=TestHelperProcess and GO_HELPER_PROCESS=1. The helper
// dispatches on os.Args after "--" and calls os.Exit when done.
//
// Single-process tests in this file use goroutines to exercise concurrent
// behaviour within a single process.

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"testing"
	"time"
)

// --------------------------------------------------------------------------
// TestMain + TestHelperProcess — helper process boilerplate
// --------------------------------------------------------------------------

func TestMain(m *testing.M) {
	// When spawned as a helper process, TestHelperProcess will call os.Exit.
	os.Exit(m.Run())
}

// TestHelperProcess is the entry point for child processes. It is not a real
// test: when GO_HELPER_PROCESS != "1" it returns immediately (passes).
func TestHelperProcess(t *testing.T) {
	if os.Getenv("GO_HELPER_PROCESS") != "1" {
		return
	}
	// Extract args after "--"
	args := os.Args
	for len(args) > 0 {
		if args[0] == "--" {
			args = args[1:]
			break
		}
		args = args[1:]
	}
	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "helper: no command")
		os.Exit(2)
	}
	switch args[0] {
	case "claim-race":
		helperClaimRace(args[1:])
	case "claim-and-hold":
		helperClaimAndHold(args[1:])
	default:
		fmt.Fprintf(os.Stderr, "helper: unknown command %q\n", args[0])
		os.Exit(2)
	}
	os.Exit(0)
}

// spawnHelper spawns the test binary itself as a helper process.
func spawnHelper(t *testing.T, args ...string) *exec.Cmd {
	t.Helper()
	cmdArgs := append([]string{"-test.run=TestHelperProcess", "--"}, args...)
	cmd := exec.Command(os.Args[0], cmdArgs...)
	cmd.Env = append(os.Environ(), "GO_HELPER_PROCESS=1")
	return cmd
}

// waitForFile polls until path exists or timeout elapses.
func waitForFile(path string, timeout time.Duration) error {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if _, err := os.Stat(path); err == nil {
			return nil
		}
		time.Sleep(10 * time.Millisecond)
	}
	return fmt.Errorf("timed out waiting for %s", path)
}

// --------------------------------------------------------------------------
// Helper implementations (run inside child processes)
// --------------------------------------------------------------------------

// helperClaimRace: wait for gate file, try to claim, write result.
// Args: cacheRoot tier name ttlMs deadlineMs readyFile startFile resultFile
func helperClaimRace(args []string) {
	if len(args) < 8 {
		fmt.Fprintln(os.Stderr, "claim-race: need 8 args")
		os.Exit(2)
	}
	cacheRoot, tier, name := args[0], args[1], args[2]
	ttlMs, _ := strconv.Atoi(args[3])
	deadlineMs, _ := strconv.Atoi(args[4])
	readyFile, startFile, resultFile := args[5], args[6], args[7]

	c := &Cache{Root: cacheRoot}
	s := Source{
		Tier:            tier,
		Name:            name,
		TTL:             time.Duration(ttlMs) * time.Millisecond,
		RefreshDeadline: time.Duration(deadlineMs) * time.Millisecond,
	}
	_ = os.MkdirAll(filepath.Join(cacheRoot, tier), 0o750)

	// Signal ready.
	_ = os.WriteFile(readyFile, []byte("ready"), 0o600)

	// Poll for start gate (max 10s).
	gateDeadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(gateDeadline) {
		if _, err := os.Stat(startFile); err == nil {
			break
		}
		time.Sleep(5 * time.Millisecond)
	}

	claim, err := c.claimRefresh(s)
	var result string
	switch {
	case err != nil:
		result = "error:" + err.Error()
	case claim.claimed:
		result = "claimed"
		// Hold the marker long enough for the peer to observe it.
		time.Sleep(5 * time.Second)
		c.releaseMarker(s)
	default:
		result = "inflight"
	}
	_ = os.WriteFile(resultFile, []byte(result), 0o600)
}

// helperClaimAndHold: claim source, signal started, then block until killed.
// Args: cacheRoot tier name ttlMs deadlineMs startedFile
func helperClaimAndHold(args []string) {
	if len(args) < 6 {
		fmt.Fprintln(os.Stderr, "claim-and-hold: need 6 args")
		os.Exit(2)
	}
	cacheRoot, tier, name := args[0], args[1], args[2]
	ttlMs, _ := strconv.Atoi(args[3])
	deadlineMs, _ := strconv.Atoi(args[4])
	startedFile := args[5]

	c := &Cache{Root: cacheRoot}
	s := Source{
		Tier:            tier,
		Name:            name,
		TTL:             time.Duration(ttlMs) * time.Millisecond,
		RefreshDeadline: time.Duration(deadlineMs) * time.Millisecond,
	}
	_ = os.MkdirAll(filepath.Join(cacheRoot, tier), 0o750)

	claim, err := c.claimRefresh(s)
	if err != nil || !claim.claimed {
		fmt.Fprintf(os.Stderr, "claim-and-hold: claim failed: %v claimed=%v\n", err, claim.claimed)
		os.Exit(1)
	}
	_ = os.WriteFile(startedFile, []byte("started"), 0o600)
	// Block until SIGKILL.
	select {}
}

// --------------------------------------------------------------------------
// Test 1 — TestConcurrentClaimTwoProcs
// --------------------------------------------------------------------------

// Two child processes race claim_refresh; exactly one returns ClaimedByMe,
// the other AlreadyInFlight.
func TestConcurrentClaimTwoProcs(t *testing.T) {
	dir := t.TempDir()
	tier, name := "discovery", "concurrent"
	ttlMs, deadlineMs := "60000", "60000"

	readyA := filepath.Join(dir, "ready_a")
	readyB := filepath.Join(dir, "ready_b")
	startFile := filepath.Join(dir, "start")
	resultA := filepath.Join(dir, "result_a")
	resultB := filepath.Join(dir, "result_b")

	cmdA := spawnHelper(t, "claim-race", dir, tier, name, ttlMs, deadlineMs, readyA, startFile, resultA)
	cmdB := spawnHelper(t, "claim-race", dir, tier, name, ttlMs, deadlineMs, readyB, startFile, resultB)

	if err := cmdA.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = cmdA.Process.Kill(); _ = cmdA.Wait() })
	if err := cmdB.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = cmdB.Process.Kill(); _ = cmdB.Wait() })

	if err := waitForFile(readyA, 10*time.Second); err != nil {
		t.Fatal(err)
	}
	if err := waitForFile(readyB, 10*time.Second); err != nil {
		t.Fatal(err)
	}

	// Release the race — both helpers see start almost simultaneously.
	if err := os.WriteFile(startFile, []byte("go"), 0o600); err != nil {
		t.Fatal(err)
	}

	if err := waitForFile(resultA, 10*time.Second); err != nil {
		t.Fatal(err)
	}
	if err := waitForFile(resultB, 10*time.Second); err != nil {
		t.Fatal(err)
	}

	rawA, _ := os.ReadFile(resultA)
	rawB, _ := os.ReadFile(resultB)
	a, b := string(rawA), string(rawB)

	claimed, inflight := 0, 0
	for _, r := range []string{a, b} {
		switch r {
		case "claimed":
			claimed++
		case "inflight":
			inflight++
		}
	}
	if claimed != 1 || inflight != 1 {
		t.Errorf("expected 1 claimed + 1 inflight; got A=%q B=%q", a, b)
	}
}

// --------------------------------------------------------------------------
// Test 2 — TestReaderDuringRefresh
// --------------------------------------------------------------------------

// 100 concurrent readers observe only valid JSON while a writer produces
// 100 versions via refreshAndCommit.
func TestReaderDuringRefresh(t *testing.T) {
	c := newTestCache(t)
	s := testSource("reader-during-refresh", time.Hour, 10*time.Second)
	_ = os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750)

	makePayload := func(v int) []byte {
		return []byte(fmt.Sprintf(`{"version":%d,"pad":"%s"}`, v, strings.Repeat("x", 512)))
	}
	if err := atomicWrite(c.dataPath(s), makePayload(0)); err != nil {
		t.Fatal(err)
	}

	const numReaders = 100
	const numVersions = 100

	stop := make(chan struct{})

	stop := make(chan struct{})
	errs := make(chan string, numReaders*10)
	var wg sync.WaitGroup

	for range numReaders {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-stop:
					return
				default:
				}
				data, err := os.ReadFile(c.dataPath(s))
				if err != nil {
					continue
				}
				if !valid[string(data)] {
					errs <- fmt.Sprintf("invalid/torn payload len=%d: %.80s", len(data), data)
				}
			}
		}()
	}

	for i := 1; i < numVersions; i++ {
		if err := atomicWrite(c.dataPath(s), payloads[i]); err != nil {
			close(stop)
			t.Fatal(err)
		}
	}

	close(stop)
	wg.Wait()
	close(errs)

	for e := range errs {
		t.Error(e)
	}
}

// --------------------------------------------------------------------------
// Test 8 — TestPruneDoesNotRaceActiveSources
// --------------------------------------------------------------------------

// Prune skips a source whose .refreshing marker is active (PID alive, deadline
// in the future). None of the source's files are removed.
func TestPruneDoesNotRaceActiveSources(t *testing.T) {
	c := newTestCache(t)
	s := Source{Tier: "discovery", Name: "active-during-prune", TTL: time.Hour, RefreshDeadline: 60 * time.Second}
	_ = os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750)

	if err := atomicWrite(c.dataPath(s), []byte(`{"preserved":true}`)); err != nil {
		t.Fatal(err)
	}
	m := &refreshMarker{
		PID:       os.Getpid(),
		StartedAt: time.Now().UTC(),
		Deadline:  time.Now().UTC().Add(60 * time.Second),
	}
	if err := writeMarker(c.markerPath(s), m); err != nil {
		t.Fatal(err)
	}

	// Prune with no active sources — s would normally be removed.
	if err := c.Prune(nil); err != nil {
		t.Fatal(err)
	}

	if _, err := os.Stat(c.dataPath(s)); os.IsNotExist(err) {
		t.Error("Prune removed data file while .refreshing marker was active")
	}
	if _, err := os.Stat(c.markerPath(s)); os.IsNotExist(err) {
		t.Error("Prune removed .refreshing marker while it was active")
	}
}

// --------------------------------------------------------------------------
// Test 9 — TestStaleWhileRevalidate
// --------------------------------------------------------------------------

// Read returns stale data immediately (≤ 5 ms). A background refresh fires
// via MaybeRefresh. After the refresh completes, subsequent Read returns fresh.
func TestStaleWhileRevalidate(t *testing.T) {
	c := newTestCache(t)
	s := testSource("stale-reval", time.Hour, 5*time.Second)
	_ = os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750)

	staleData := []byte(`{"v":"stale"}`)
	freshData := []byte(`{"v":"fresh"}`)

	if err := atomicWrite(c.dataPath(s), staleData); err != nil {
		t.Fatal(err)
	}
	past := time.Now().Add(-2 * time.Hour)
	_ = os.Chtimes(c.dataPath(s), past, past)

	// Read must return stale data immediately (≤ 5 ms).
	start := time.Now()
	res, err := c.Read(s)
	readLatency := time.Since(start)
	if err != nil {
		t.Fatal(err)
	}
	if readLatency > 5*time.Millisecond {
		t.Errorf("Read() took %v, want ≤ 5ms", readLatency)
	}
	if string(res.Data) != string(staleData) {
		t.Errorf("Read() = %q, want stale", res.Data)
	}
	if !res.Stale {
		t.Error("expected Stale=true for backdated file")
	}

	// Trigger background refresh; MaybeRefresh returns immediately.
	c.MaybeRefresh(s, func(_ context.Context) ([]byte, error) {
		time.Sleep(50 * time.Millisecond)
		return freshData, nil
	})

	// Poll until fresh data appears (max 5 s).
	refreshDeadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(refreshDeadline) {
		r, _ := c.Read(s)
		if string(r.Data) == string(freshData) {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}

	res2, err := c.Read(s)
	if err != nil {
		t.Fatal(err)
	}
	if string(res2.Data) != string(freshData) {
		t.Errorf("after background refresh, Read() = %q, want fresh", res2.Data)
	}
	if !res2.Fresh {
		t.Errorf("expected Fresh=true after refresh, Age=%v TTL=%v", res2.Age, s.TTL)
	}
}

// --------------------------------------------------------------------------
// Test 10 — TestPIDReuseSafety
// --------------------------------------------------------------------------

// A marker whose PID is "reused" by an unrelated live process (simulated by
// using this process's PID) is treated as stale once the deadline + 2×
// RefreshDeadline has passed. The deadline check is the safety net.
func TestPIDReuseSafety(t *testing.T) {
	c := newTestCache(t)
	s := testSource("pid-reuse", time.Hour, 1*time.Second)
	_ = os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750)

	// PID = this process (alive = simulates PID reuse); deadline expired > 2×1s ago.
	expiredDeadline := time.Now().Add(-3 * time.Second)
	m := &refreshMarker{
		PID:       os.Getpid(),
		StartedAt: expiredDeadline.Add(-time.Second),
		Deadline:  expiredDeadline,
	}
	if err := writeMarker(c.markerPath(s), m); err != nil {
		t.Fatal(err)
	}

	// Verify the PID is indeed alive (confirming PID-reuse scenario).
	if !processAlive(os.Getpid()) {
		t.Fatal("precondition: current PID must be alive")
	}
