	}

	claim, err := c.claimRefresh(s)
	if err != nil {
		t.Fatalf("claimRefresh: %v", err)
	}
	if !claim.claimed {
		t.Error("expected ClaimedByMe: PID alive but deadline expired; deadline check is the safety net")
	}
	c.releaseMarker(s)
}

