const (
	discoveryTTLHTTPRemote       = 24 * time.Hour
	discoveryTTLHTTPLocal        = time.Hour
	discoveryTTLPTY              = 24 * time.Hour
	discoveryRefreshDeadlineHTTP = 10 * time.Second
	discoveryRefreshDeadlinePTY  = 60 * time.Second
)

type discoveredModel struct {
	Provider        string
	ProviderType    string
	Harness         string
	ID              string
	Configured      bool
	EndpointName    string
	EndpointBaseURL string
	ServerInstance  string
	Via             Source
	DiscoveredAt    time.Time
}

type modelDiscoveryEndpoint struct {
	Name           string
	BaseURL        string
	ServerInstance string
}

type providerDiscoveryResult struct {
	Models  []discoveredModel
	Sources map[string]SourceMeta
}

type discoveryPayload struct {
	CapturedAt      time.Time `json:"captured_at"`
	Models          []string  `json:"models,omitempty"`
	ReasoningLevels []string  `json:"reasoning_levels,omitempty"`
	Source          string    `json:"source,omitempty"`
}

func discoverProvider(ctx context.Context, providerName string, pc config.ProviderConfig, cache *discoverycache.Cache, opts AssembleOptions) providerDiscoveryResult {
	providerType := normalizeProviderType(pc.Type)
	switch providerType {
	case "claude", "codex":
		return discoverHarnessProvider(providerName, providerType, cache, opts)
	case "openai", "openrouter", "vidar-ds4", "sindri-llamacpp", "ds4", "lmstudio", "llama-server", "omlx", "rapid-mlx", "vllm", "ollama", "minimax", "qwen", "zai":
		result := discoverOpenAICompatibleProvider(ctx, providerName, pc, cache, opts)
		if providerType == "ds4" || providerType == "vidar-ds4" {
			result.merge(discoverPropsProvider(providerName, pc, cache))
		}
		return result
	default:
		if strings.TrimSpace(pc.Model) == "" {
			return providerDiscoveryResult{Sources: map[string]SourceMeta{}}
		}
		return providerDiscoveryResult{
			Models: []discoveredModel{{
				Provider:        providerName,
				ProviderType:    providerType,
				ID:              strings.TrimSpace(pc.Model),
				EndpointName:    endpointNameForConfig(providerName, pc.BaseURL, pc.Endpoints),
				EndpointBaseURL: firstBaseURL(pc),
				ServerInstance:  firstServerInstance(pc),
				Via:             SourceNativeAPI,
				DiscoveredAt:    time.Now().UTC(),
			}},
			Sources: map[string]SourceMeta{
				providerName: {LastRefreshedAt: time.Now().UTC()},
			},
		}
	}
}

func discoverOpenAICompatibleProvider(ctx context.Context, providerName string, pc config.ProviderConfig, cache *discoverycache.Cache, opts AssembleOptions) providerDiscoveryResult {
	if cache == nil {
		return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName: {Stale: true, Error: "discovery cache is nil"}}}
	}
	endpoints := discoveryEndpoints(providerName, pc)
	if len(endpoints) == 0 {
		endpoints = []modelDiscoveryEndpoint{{
			Name:           endpointNameForConfig(providerName, pc.BaseURL, nil),
			BaseURL:        firstBaseURL(pc),
			ServerInstance: firstServerInstance(pc),
		}}
	}
	result := providerDiscoveryResult{Sources: map[string]SourceMeta{}}
	for _, endpoint := range endpoints {
		endpointResult := discoverOpenAICompatibleEndpoint(ctx, providerName, providerTypeFromProviderConfig(pc), endpoint, pc.APIKey, discoveryTTLForProvider(pc), cache, opts)
		result.merge(endpointResult)
	}
	if len(result.Models) == 0 && strings.TrimSpace(pc.Model) != "" {
		fallback := modelsFromIDs([]string{pc.Model}, SourceNativeAPI, time.Now().UTC(), discoveryIdentity{
			Provider:        providerName,
			ProviderType:    providerTypeFromProviderConfig(pc),
			EndpointName:    endpointNameForConfig(providerName, pc.BaseURL, pc.Endpoints),
			EndpointBaseURL: firstBaseURL(pc),
			ServerInstance:  firstServerInstance(pc),
		})
		for i := range fallback.Models {
			fallback.Models[i].Configured = true
		}
		result.merge(fallback)
		meta := result.Sources[providerName]
		if meta.LastRefreshedAt.IsZero() {
			meta.LastRefreshedAt = time.Now().UTC()
		}
		result.Sources[providerName] = meta
	}
	return result
}

func discoverOpenAICompatibleEndpoint(ctx context.Context, providerName, providerType string, endpoint modelDiscoveryEndpoint, apiKey string, ttl time.Duration, cache *discoverycache.Cache, opts AssembleOptions) providerDiscoveryResult {
	src := discoverySource(endpointSourceName(providerName, endpoint.Name, endpoint.BaseURL, endpoint.ServerInstance), ttl, discoveryRefreshDeadlineHTTP)
	refresher := func(refreshCtx context.Context) ([]byte, error) {
		requestCtx := ctx
		if requestCtx == nil {
			requestCtx = refreshCtx
		}
		ids, err := openaiadapter.DiscoverModels(requestCtx, strings.TrimRight(endpoint.BaseURL, "/"), apiKey)
		if err != nil {
			return nil, err
		}
		return json.Marshal(discoveryPayload{
			CapturedAt: time.Now().UTC(),
			Models:     ids,
			Source:     "openai-compatible:/v1/models",
		})
	}
	if opts.Refresh == RefreshForce {
		_ = cache.Refresh(src, refresher)
	} else if opts.Refresh != RefreshNone {
		cache.MaybeRefresh(src, refresher)
	}
	return readDiscoveryCache(cache, src, providerName, SourceNativeAPI, discoveryIdentity{
		Provider:        providerName,
		ProviderType:    providerType,
		EndpointName:    endpoint.Name,
		EndpointBaseURL: endpoint.BaseURL,
		ServerInstance:  endpoint.ServerInstance,
	})
}

func discoverPropsProvider(providerName string, pc config.ProviderConfig, cache *discoverycache.Cache) providerDiscoveryResult {
	if cache == nil {
		return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName + ":props": {Stale: true, Error: "discovery cache is nil"}}}
	}
	src := discoverySource(providerName+"-props", discoveryTTLHTTPLocal, discoveryRefreshDeadlineHTTP)
	result := readDiscoveryCache(cache, src, providerName, SourcePropsAPI, discoveryIdentity{
		Provider:        providerName,
		ProviderType:    providerTypeFromProviderConfig(pc),
		EndpointName:    endpointNameForConfig(providerName, pc.BaseURL, pc.Endpoints),
		EndpointBaseURL: firstBaseURL(pc),
		ServerInstance:  firstServerInstance(pc),
	})
	renamed := make(map[string]SourceMeta, len(result.Sources))
	for _, meta := range result.Sources {
		renamed[providerName+":props"] = meta
	}
	result.Sources = renamed
	return result
}

func discoverHarnessProvider(providerName, providerType string, cache *discoverycache.Cache, opts AssembleOptions) providerDiscoveryResult {
	src := discoverycache.Source{
		Tier:            "discovery",
		Name:            providerName,
		TTL:             discoveryTTLPTY,
		RefreshDeadline: discoveryRefreshDeadlinePTY,
	}
	if cache == nil {
		snapshot, err := harnesses.CachedModelDiscoverySnapshot(providerType, harnesses.EmbeddedDiscoverySource)
		if err != nil {
			return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName: {Stale: true, Error: err.Error()}}}
		}
		return modelsFromIDs(snapshot.Models, SourceHarnessPTY, snapshot.CapturedAt, discoveryIdentity{
			Provider:       providerName,
			ProviderType:   providerType,
			Harness:        providerType,
			EndpointName:   providerName,
			ServerInstance: providerName,
		})
	}
	if opts.Refresh == RefreshForce {
		_ = cache.Refresh(src, func(context.Context) ([]byte, error) {
			snapshot, err := harnesses.CachedModelDiscoverySnapshot(providerType, harnesses.EmbeddedDiscoverySource)
			if err != nil {
				return nil, err
			}
			return json.Marshal(discoveryPayload{
				CapturedAt:      snapshot.CapturedAt,
				Models:          snapshot.Models,
				ReasoningLevels: snapshot.ReasoningLevels,
				Source:          snapshot.Source,
			})
		})
	}
	result := readDiscoveryCache(cache, src, providerName, SourceHarnessPTY, discoveryIdentity{
		Provider:       providerName,
		ProviderType:   providerType,
		Harness:        providerType,
		EndpointName:   providerName,
		ServerInstance: providerName,
	})
	if len(result.Models) > 0 {
		return result
	}
	snapshot, err := harnesses.CachedModelDiscoverySnapshot(providerType, harnesses.EmbeddedDiscoverySource)
	if err != nil {
		if result.Sources == nil {
			result.Sources = map[string]SourceMeta{}
		}
		meta := result.Sources[providerName]
		meta.Error = err.Error()
		result.Sources[providerName] = meta
		return result
	}
	return modelsFromIDs(snapshot.Models, SourceHarnessPTY, snapshot.CapturedAt, discoveryIdentity{
		Provider:       providerName,
		ProviderType:   providerType,
		Harness:        providerType,
		EndpointName:   providerName,
		ServerInstance: providerName,
	})

package modelregistry

import (
	"context"
	"os/exec"
	"sort"
	"time"

	"github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
)

// RefreshMode controls whether Assemble refreshes stale source cache data.
type RefreshMode int

const (
	// RefreshBackground preserves the default stale-while-revalidate behavior:
	// return cached data immediately and refresh stale sources in the background.
	RefreshBackground RefreshMode = iota
	// RefreshNone returns cached data only.
	RefreshNone
	// RefreshForce refreshes sources synchronously before reading them.
	RefreshForce
)

// AssembleOptions controls snapshot assembly behavior.
type AssembleOptions struct {
	Refresh RefreshMode
}

// Assemble builds a ModelSnapshot from configured providers, cache-backed
// discovery, runtime status cache state, and model catalog metadata.
func Assemble(ctx context.Context, cfg *config.Config, cat *modelcatalog.Catalog, cache *discoverycache.Cache) (ModelSnapshot, error) {
	return AssembleWithOptions(ctx, cfg, cat, cache, AssembleOptions{Refresh: RefreshBackground})
}

// AssembleWithOptions builds a ModelSnapshot with explicit cache refresh
// behavior for CLI and routing consumers.
func AssembleWithOptions(ctx context.Context, cfg *config.Config, cat *modelcatalog.Catalog, cache *discoverycache.Cache, opts AssembleOptions) (ModelSnapshot, error) {
	asOf := nowUTC()
	snapshot := ModelSnapshot{
		AsOf:    asOf,
		Sources: map[string]SourceMeta{},
	}
	if cfg == nil {
		return snapshot, nil
	}

	providers := enumerateProviders(cfg)
	names := make([]string, 0, len(providers))
	for name := range providers {
		names = append(names, name)
	}
	sort.Strings(names)

	for _, providerName := range names {
		pcfg := providers[providerName]
		discovered := discoverProvider(ctx, providerName, pcfg, cache, opts)
		for source, meta := range discovered.Sources {
			snapshot.Sources[source] = meta
		}
		includeByDefault := effectiveProviderIncludeByDefault(providerName, pcfg, cat)
		billing := effectiveProviderBilling(providerName, pcfg, cat)
		status := providerStatus(cache, providerName)
		for _, discoveredModel := range discovered.Models {
			model := KnownModel{
				Provider:         providerName,
				ProviderType:     discoveredModel.ProviderType,
				Harness:          discoveredModel.Harness,
				ID:               discoveredModel.ID,
				Configured:       discoveredModel.Configured,
				EndpointName:     discoveredModel.EndpointName,
				EndpointBaseURL:  discoveredModel.EndpointBaseURL,
				ServerInstance:   discoveredModel.ServerInstance,
				Billing:          billing,
				IncludeByDefault: includeByDefault,
				DiscoveredVia:    discoveredModel.Via,
				DiscoveredAt:     discoveredModel.DiscoveredAt,
				Status:           status,
			}
			model = enrichModel(model, includeByDefault, cat)
			model = attachRuntimeSignals(model, cache)
			snapshot.Models = append(snapshot.Models, model)
		}
	}
	sort.Slice(snapshot.Models, func(i, j int) bool {
		if snapshot.Models[i].Provider != snapshot.Models[j].Provider {
			return snapshot.Models[i].Provider < snapshot.Models[j].Provider
		}
		if snapshot.Models[i].ProviderType != snapshot.Models[j].ProviderType {
			return snapshot.Models[i].ProviderType < snapshot.Models[j].ProviderType
		}
		if snapshot.Models[i].Harness != snapshot.Models[j].Harness {
			return snapshot.Models[i].Harness < snapshot.Models[j].Harness
		}
		if snapshot.Models[i].EndpointName != snapshot.Models[j].EndpointName {
			return snapshot.Models[i].EndpointName < snapshot.Models[j].EndpointName
		}
		if snapshot.Models[i].EndpointBaseURL != snapshot.Models[j].EndpointBaseURL {
			return snapshot.Models[i].EndpointBaseURL < snapshot.Models[j].EndpointBaseURL
		}
		if snapshot.Models[i].ServerInstance != snapshot.Models[j].ServerInstance {
			return snapshot.Models[i].ServerInstance < snapshot.Models[j].ServerInstance
		}
		return snapshot.Models[i].ID < snapshot.Models[j].ID
	})
	return snapshot, nil
}

// ActiveSources returns the cache sources that are currently configured and
// should be preserved by cache garbage collection.
func ActiveSources(cfg *config.Config) []discoverycache.Source {
	if cfg == nil {
		return nil
	}
	providers := enumerateProviders(cfg)
	names := make([]string, 0, len(providers))
	for name := range providers {
		names = append(names, name)
	}
	sort.Strings(names)

	sources := make([]discoverycache.Source, 0, len(names)*2)
	for _, providerName := range names {
		pcfg := providers[providerName]
		switch normalizeProviderType(pcfg.Type) {
		case "claude", "codex":
			sources = append(sources, discoverycache.Source{
				Tier:            "discovery",
				Name:            providerName,
				TTL:             discoveryTTLPTY,
				RefreshDeadline: discoveryRefreshDeadlinePTY,
			})
		case "openai", "openrouter", "vidar-ds4", "sindri-llamacpp", "ds4", "lmstudio", "llama-server", "omlx", "rapid-mlx", "vllm", "ollama", "minimax", "qwen", "zai":
			for _, endpoint := range discoveryEndpoints(providerName, pcfg) {
				sources = append(sources, discoverySource(endpointSourceName(providerName, endpoint.Name, endpoint.BaseURL, endpoint.ServerInstance), discoveryTTLForProvider(pcfg), discoveryRefreshDeadlineHTTP))
			}
			if normalizeProviderType(pcfg.Type) == "ds4" || normalizeProviderType(pcfg.Type) == "vidar-ds4" {
				sources = append(sources, discoverySource(providerName+"-props", discoveryTTLHTTPLocal, discoveryRefreshDeadlineHTTP))
			}
		default:
			if pcfg.Model != "" {
				sources = append(sources, discoverySource(providerName, discoveryTTLHTTPRemote, discoveryRefreshDeadlineHTTP))
			}
		}
		sources = append(sources, discoverycache.Source{
			Tier:            "runtime",
			Name:            providerName,
			TTL:             5 * time.Minute,
			RefreshDeadline: 5 * time.Second,
		})
	}
	return sources
}

func enumerateProviders(cfg *config.Config) map[string]config.ProviderConfig {
	out := make(map[string]config.ProviderConfig, len(cfg.Providers)+2)
	for name, pc := range cfg.Providers {
		out[name] = pc
	}
	addImplicitHarness(out, "claude-subscription", "claude", "claude")
	addImplicitHarness(out, "codex-subscription", "codex", "codex")
	return out
}

func addImplicitHarness(providers map[string]config.ProviderConfig, name, providerType, binary string) {
	if _, exists := providers[name]; exists {
		return
	}
	if _, err := exec.LookPath(binary); err != nil {
		return
	}
	include := true
	providers[name] = config.ProviderConfig{
		Type:             providerType,
		IncludeByDefault: &include,
		Billing:          string(modelcatalog.BillingModelSubscription),
	}
}

package runtimesignals

import (
	"context"
	"encoding/json"
	"net/http"
	"sync"
	"time"

	"github.com/easel/fizeau/internal/discoverycache"
	claudecache "github.com/easel/fizeau/internal/harnesses/claude"
	codexcache "github.com/easel/fizeau/internal/harnesses/codex"
	geminicache "github.com/easel/fizeau/internal/harnesses/gemini"
	"github.com/easel/fizeau/internal/provider/quotaheaders"
)

const (
	// RuntimeTTL is the default cache TTL for runtime signals (ADR-012 §2).
	RuntimeTTL = 5 * time.Minute
	// RuntimeRefreshDeadline bounds how long a runtime signal refresh may take.
	RuntimeRefreshDeadline = 5 * time.Second

	defaultWindowSize = 100
	aliveCheckTimeout = 3 * time.Second
)

// Store is the per-process in-memory state for runtime signal collection.
// It holds per-provider latency windows and the most recently observed
// rate-limit header signals. All methods are safe for concurrent use.
type Store struct {
	mu        sync.RWMutex
	latencies map[string]*LatencyWindow
	headers   *headerStore
}

// CollectInput describes the provider identity needed to assemble a runtime
// signal. Type controls the collection path; BaseURL is used by local
// providers for the live /v1/models check.
type CollectInput struct {
	Type    string
	BaseURL string
}

// NewStore creates an empty Store ready for use.
func NewStore() *Store {
	return &Store{
		latencies: make(map[string]*LatencyWindow),
		headers:   newHeaderStore(),
	}
}

// DefaultStore is the process-singleton Store used by the package-level
// RecordResponse and Collect functions.
var DefaultStore = NewStore()

// RecordResponse records an HTTP response observation for a provider using the
// DefaultStore. providerType controls which header parser is applied
// ("openrouter", "anthropic", or any other value for the OpenAI parser).
func RecordResponse(provider string, h http.Header, latency time.Duration, providerType string) {
	DefaultStore.RecordResponse(provider, h, latency, providerType)
}

// RecordResponse records an HTTP response observation. It updates both the
// latency window and the header signal store for the named provider.
func (s *Store) RecordResponse(provider string, h http.Header, latency time.Duration, providerType string) {
	win := s.latencyWindow(provider)
	win.Record(latency)

	if h != nil {
		now := time.Now()
		var sig quotaheaders.Signal
		switch providerType {
		case "openrouter":
			sig = quotaheaders.ParseOpenRouter(h, now)
		case "anthropic":
			sig = quotaheaders.ParseAnthropic(h, now)
		default:
			sig = quotaheaders.ParseOpenAI(h, now)
		}
		s.headers.record(provider, sig)
	}
}

// Collect assembles a runtime Signal for the named provider using
// DefaultStore.
func Collect(ctx context.Context, providerName string, cfg CollectInput) (Signal, error) {
	return DefaultStore.Collect(ctx, providerName, cfg)
}

// Collect assembles a runtime Signal for providerName. The cfg.Type field
// controls which collection path is used:
//
//   - "claude"       → existing internal/harnesses/claude/quota_cache.go
//   - "codex"        → existing internal/harnesses/codex/quota_cache.go
//   - "gemini"       → existing internal/harnesses/gemini/quota_cache.go
//   - "openrouter"   → most recently recorded rate-limit headers (OpenRouter parser)
//   - "openai", "anthropic", and unknown HTTP types → rate-limit headers
//   - local types    → HTTP GET /v1/models alive check (no quota concept)
func (s *Store) Collect(ctx context.Context, providerName string, cfg CollectInput) (Signal, error) {
	sig := Signal{
		Provider:   providerName,
		Status:     StatusUnknown,
		RecordedAt: time.Now().UTC(),
	}

	s.mu.RLock()
	win := s.latencies[providerName]
	s.mu.RUnlock()
	if win != nil {
		sig.RecentP50Latency = win.P50()
	}

	providerType := cfg.Type

	switch providerType {
	case "claude":
		collectClaudeSignal(&sig)
	case "codex":
		collectCodexSignal(&sig)
	case "gemini":
		collectGeminiSignal(&sig)
	case "ds4", "llama-server", "omlx", "lmstudio", "lucebox", "vllm", "rapid-mlx", "ollama":
		collectLocalSignal(ctx, cfg.BaseURL, &sig)
	default:
		s.collectHeaderSignal(providerName, &sig)
	}

	return sig, nil
}

// CacheSource returns the discoverycache.Source descriptor for a provider's
// runtime signal. The file path resolves to runtime/<provider>.json.
func CacheSource(providerName string) discoverycache.Source {
	return discoverycache.Source{
		Tier:            "runtime",
		Name:            providerName,
		TTL:             RuntimeTTL,
		RefreshDeadline: RuntimeRefreshDeadline,
	}
}

// Write serializes sig and stores it in M1's runtime cache tier. The cache
// file lands at <cache.Root>/runtime/<sig.Provider>.json.
func Write(cache *discoverycache.Cache, sig Signal) error {
	data, err := json.Marshal(sig)
	if err != nil {
		return err
	}
	src := CacheSource(sig.Provider)
	return cache.Refresh(src, func(_ context.Context) ([]byte, error) {
		return data, nil
	})
}

// ReadCached reads a Signal from M1's runtime cache for providerName.
// Returns (nil, false) when the entry is absent or cannot be decoded.
func ReadCached(cache *discoverycache.Cache, providerName string) (*Signal, bool) {
	src := CacheSource(providerName)
	result, err := cache.Read(src)
	if err != nil || result.Data == nil {
		return nil, false
	}
	var sig Signal
	if err := json.Unmarshal(result.Data, &sig); err != nil {
		return nil, false
	}
	return &sig, true
}

// ---- per-provider-type collectors -------------------------------------------

func collectClaudeSignal(sig *Signal) {
	snap, ok := claudecache.ReadClaudeQuota()
	if !ok || snap == nil {
		return // StatusUnknown
	}
	if claudecache.ClaudeQuotaSnapshotAge(snap, time.Now()) > claudecache.DefaultClaudeQuotaStaleAfter {
		return // StatusUnknown; snapshot is stale
	}
	if snap.WeeklyRemaining <= 0 || snap.FiveHourRemaining <= 0 {
		sig.Status = StatusExhausted
		zero := 0
		sig.QuotaRemaining = &zero
		return
	}
	sig.Status = StatusAvailable
	rem := snap.FiveHourRemaining
	sig.QuotaRemaining = &rem
}

func collectCodexSignal(sig *Signal) {
	snap, ok := codexcache.ReadCodexQuota()
	if !ok || snap == nil {
		return // StatusUnknown
	}
	if codexcache.CodexQuotaSnapshotAge(snap, time.Now()) > codexcache.DefaultCodexQuotaStaleAfter {
		return // StatusUnknown; snapshot is stale
	}
	for _, w := range snap.Windows {
		if w.UsedPercent >= 95 || w.State == "blocked" {
			sig.Status = StatusExhausted
			zero := 0
			sig.QuotaRemaining = &zero
			return
		}
	}
	sig.Status = StatusAvailable
}

func collectGeminiSignal(sig *Signal) {
	snap, ok := geminicache.ReadGeminiQuota()
	if !ok || snap == nil {
		return // StatusUnknown
	}
	if geminicache.GeminiQuotaSnapshotAge(snap, time.Now()) > geminicache.DefaultGeminiQuotaStaleAfter {
		return // StatusUnknown; snapshot is stale
	}
	decision := geminicache.DecideGeminiQuotaRouting(snap, time.Now(), 0)
	if decision.PreferGemini {
		sig.Status = StatusAvailable
	} else {
		sig.Status = StatusExhausted
		zero := 0
		sig.QuotaRemaining = &zero
	}
}

// collectHeaderSignal reads the most recently recorded rate-limit header signal
// for the provider and populates sig accordingly.
func (s *Store) collectHeaderSignal(providerName string, sig *Signal) {
	hSig, ok := s.headers.get(providerName)
	if !ok {
		return // StatusUnknown; no headers observed yet
	}
	exhausted, retryAfter := hSig.IsExhausted(time.Now())
	if exhausted {
		sig.Status = StatusExhausted
		zero := 0
		sig.QuotaRemaining = &zero
		if !retryAfter.IsZero() {
			t := retryAfter
			sig.QuotaResetAt = &t
		}
		return
	}
	sig.Status = StatusAvailable
	switch {
	case hSig.RemainingRequests >= 0:
		rem := int(hSig.RemainingRequests)
		sig.QuotaRemaining = &rem
	case hSig.RemainingTokens >= 0:
		rem := int(hSig.RemainingTokens)
		sig.QuotaRemaining = &rem
	}
	if !hSig.ResetTime.IsZero() {
		t := hSig.ResetTime
		sig.QuotaResetAt = &t
	}
}

