	want, err := modelsnapshot.AssembleWithOptions(context.Background(), wantCfg, cat, cache, modelsnapshot.AssembleOptions{Refresh: modelsnapshot.RefreshNone})
	if err != nil {
		t.Fatalf("modelsnapshot.AssembleWithOptions: %v", err)
